#!/bin/bash
# Build the WRF v4.8.0 km_opt=3 Smagorinsky oracle used for
# tests/atmosphere/oracle_fixtures/smag_wrf_km3.npz.
# usage: build.sh <WRF checkout at v4.8.0 06d4240ae9> <build dir> <module_model_constants.F>
# dyn_em/module_diffusion_em.F is compiled UNMODIFIED (copied, cmp-checked) against
# stubs.F90 and a module_model_constants generated by make_fixture.py from WRF's own
# share/module_model_constants.F with legoESM's g, R_d, c_pd, R_v, L_v, p_ref,
# T_freeze and the run's Prandtl number substituted.  fp64 via -fdefault-real-8.
# Run on a compute node.
set -euo pipefail
WRF=$(cd "$1" && pwd); mkdir -p "$2"; B=$(cd "$2" && pwd); CONST=$(readlink -f "$3")
HERE=$(cd "$(dirname "$0")" && pwd)
SHA=$(git -C "$WRF" rev-parse HEAD)
[ "$SHA" = 06d4240ae989cc3e50af412bb472df3d9048783c ] || { echo "WRF SHA $SHA is not v4.8.0"; exit 1; }
FC=${FC:-gfortran}
FFLAGS="-O0 -g -fno-fast-math -fdefault-real-8 -fdefault-double-8 -ffpe-trap=invalid,zero,overflow -ffree-line-length-none -cpp -DEM_CORE=1"
$FC --version | head -1
cd "$B"
cp "$WRF/dyn_em/module_diffusion_em.F" module_diffusion_em.F
cmp module_diffusion_em.F "$WRF/dyn_em/module_diffusion_em.F"
sha256sum module_diffusion_em.F
cp "$CONST" module_model_constants.F
$FC $FFLAGS -ffree-form -c module_model_constants.F
$FC $FFLAGS -c "$HERE/stubs.F90"
$FC $FFLAGS -ffree-form -c module_diffusion_em.F
$FC $FFLAGS -c "$HERE/driver.F90"
$FC $FFLAGS -o drv_smag module_model_constants.o stubs.o module_diffusion_em.o driver.o
echo "BUILD_OK $B/drv_smag"
